<?php

namespace App\Modules\Storefront\Support\CustomThemes;

use App\Modules\Storefront\Enums\CustomThemeTemplate;
use Twig\Markup;

/**
 * The variable reference of the theme documentation, generated by walking the template
 * context ThemeFixtures builds through the real presenters (so it always matches what a
 * template receives). Lists are described by their first item (`products[]`).
 *
 *   ThemeVariableReference::globals()             → [['path' => 'store.name', 'type' => 'string', 'example' => '…'], …]
 *   ThemeVariableReference::page(Template::Cart)   → page-only variables
 *   ThemeVariableReference::markdown()             → the docs/themes/README.md section
 */
final class ThemeVariableReference
{
    public const BEGIN = '<!-- variables:begin (generated by php artisan storefront:theme-docs) -->';

    public const END = '<!-- variables:end -->';

    /**
     * @return list<array{path: string, type: string, example: string}>
     */
    public static function globals(): array
    {
        return self::walk(ThemeFixtures::globals());
    }

    /**
     * @return list<array{path: string, type: string, example: string}>
     */
    public static function page(CustomThemeTemplate $template): array
    {
        $globals = array_keys(ThemeFixtures::globals());
        $context = array_diff_key(ThemeFixtures::context($template), array_flip($globals));

        return self::walk($context);
    }

    public static function markdown(): string
    {
        $out = [self::BEGIN, '', '### Globals (every template)', '', ...self::table(self::globals())];

        foreach (CustomThemeTemplate::pages() as $template) {
            $out[] = '';
            $out[] = sprintf('### `%s` (%s)', $template->file(), implode(', ', $template->views()));
            $out[] = '';
            array_push($out, ...self::table(self::page($template)));
        }

        $out[] = '';
        $out[] = self::END;

        return implode("\n", $out);
    }

    /**
     * @param  list<array{path: string, type: string, example: string}>  $rows
     * @return list<string>
     */
    private static function table(array $rows): array
    {
        $lines = ['| Variable | Type | Example |', '|---|---|---|'];

        foreach ($rows as $row) {
            $lines[] = sprintf('| `%s` | %s | %s |', $row['path'], $row['type'], $row['example'] === '' ? '' : '`'.str_replace(['|', '`'], ['\|', "'"], $row['example']).'`');
        }

        return $lines;
    }

    /**
     * @return list<array{path: string, type: string, example: string}>
     */
    private static function walk(mixed $value, string $path = ''): array
    {
        if (is_array($value) && $value !== [] && ! array_is_list($value)) {
            $rows = $path !== '' ? [['path' => $path, 'type' => 'object', 'example' => '']] : [];

            foreach ($value as $key => $item) {
                array_push($rows, ...self::walk($item, $path === '' ? (string) $key : $path.'.'.$key));
            }

            return $rows;
        }

        if (is_array($value) && $value !== []) {
            return [['path' => $path, 'type' => 'list', 'example' => count($value).' item(s)'], ...self::walk($value[0], $path.'[]')];
        }

        return [['path' => $path, 'type' => self::type($value), 'example' => self::example($value)]];
    }

    private static function type(mixed $value): string
    {
        return match (true) {
            $value instanceof Markup => 'html (safe)',
            is_bool($value) => 'bool',
            is_int($value) => 'int',
            is_float($value) => 'float',
            is_string($value) => 'string',
            is_array($value) => 'list',
            default => 'null',
        };
    }

    private static function example(mixed $value): string
    {
        // Host-independent examples (the docs must not depend on APP_URL).
        if (is_string($value)) {
            $value = str_replace(rtrim(url('/'), '/'), 'https://your-store.com', $value);
        }

        return match (true) {
            $value instanceof Markup => mb_strimwidth((string) $value, 0, 60, '…'),
            is_bool($value) => $value ? 'true' : 'false',
            is_scalar($value) => mb_strimwidth((string) $value, 0, 60, '…'),
            default => '',
        };
    }
}
